import { serverLogger as logger } from "../../utils/index.js";
export class APIServer {
    options;
    constructor(options) {
        this.options = options;
    }
    async handleRequest(pathname) {
        if (!pathname.startsWith("/_veryfront/data/"))
            return null;
        const slug = pathname.replace("/_veryfront/data/", "").replace(".json", "");
        const pageSlug = slug || "index";
        try {
            const result = await this.options.renderer.renderPage(pageSlug);
            return new Response(JSON.stringify({
                slug,
                frontmatter: result.frontmatter,
                headings: result.headings,
                html: result.html,
            }), {
                headers: {
                    "content-type": "application/json",
                    "cache-control": "no-cache",
                },
            });
        }
        catch (error) {
            logger.error(`Error rendering page data for ${slug}:`, error);
            return new Response(JSON.stringify({
                error: "Failed to render page data",
            }), {
                status: 500,
                headers: {
                    "content-type": "application/json",
                    "cache-control": "no-store",
                },
            });
        }
    }
}
